const fs=require('fs');
const d=require('./docs/research/jev-experiments/routing/dataset.json');
const predicted=JSON.parse(fs.readFileSync('/tmp/routing-baseline.json','utf8'));
const count={}; const ids=new Set(); const issues=[];
for (let i=0;i<d.length;i++) {
 const x=d[i]; count[`${x.task}/${x.split}`]=(count[`${x.task}/${x.split}`]||0)+1;
 if(ids.has(x.id)) issues.push(`duplicate:${x.id}`); ids.add(x.id);
 for(const key of ['id','task','split','state','criteria','expected','rationale','provenance','tags','baseline']) if(!(key in x)) issues.push(`missing:${x.id}:${key}`);
 if(x.expected not in x.criteria) issues.push(`expected:${x.id}`);
 if(x.baseline not in x.criteria) issues.push(`baseline:${x.id}`);
 if(predicted[i]!==x.baseline) issues.push(`recompute:${x.id}:${predicted[i]}!=${x.baseline}`);
}
for(const task of ['R1','R2','R3','R4','R5','R6']) for(const split of ['dev','holdout']) if(count[`${task}/${split}`]!==24)issues.push(`count:${task}/${split}:${count[`${task}/${split}`]}`);
console.log(JSON.stringify({cases:d.length,counts:count,uniqueIds:ids.size,issues},null,2));
if(issues.length)process.exit(1);
NODE
