+      });
+      this.#logger.info('Decision shadow failure-triage comparison', {
+        eventType: 'decision_shadow.failure_triage',
+        requestId: observation.evidence.requestId,
+        provider: observation.evidence.provider,
+        model: observation.evidence.model,
+        requestedModel,
+        resolvedModel: prediction.resolvedModel,
+        latencyMs: Math.max(0, this.#now() - startedAt),
+        cost: prediction.costUsdMicros ?? 'unknown',
+        predictedCategory: prediction.category,
+        predictedRetry: prediction.retry,
+        confidence: prediction.confidence,
+        comparisonErrorKind: observation.comparison.errorKind,
+        comparisonRetryable: observation.comparison.retryable,
+        observedOutcome: observation.comparison.observedOutcome,
+      });
+    });
+  }
