+  }
+  for (const fixture of input.failureTriage) {
+    try {
+      const prediction = await evaluateFailureTriage({
+        client: input.client,
+        model: input.model,
+        evidence: fixture.evidence,
+      });
+      if (prediction.category === fixture.expected.category && prediction.retry === fixture.expected.retry) correct++;
+    } catch (error) {
+      errors.push({ fixtureId: fixture.id, error: error instanceof Error ? error.message : String(error) });
+    }
+  }
+  return {
+    total: input.toolSelection.length + input.failureTriage.length,
+    correct,
